-- =============================================================================
-- 001 — Master data: categories, brands, sizes, colors, suppliers, customers,
--       products and product variants.
--
-- Conventions
--   * UUID primary keys generated by PostgreSQL (gen_random_uuid, PG 13+).
--   * status: 'active' | 'inactive' (records are deactivated instead of deleted
--     when they are referenced elsewhere).
--   * Text uniqueness is case-insensitive (unique indexes on lower(...)).
--   * Optional text is stored as '' (never NULL); optional money is NULL.
--   * Constraint names are referenced by src/common/errors/constraint-messages.ts
--     to produce user-friendly API errors — keep them in sync.
-- =============================================================================

CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

-- -----------------------------------------------------------------------------
-- Categories
-- -----------------------------------------------------------------------------
CREATE TABLE categories (
  id          uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  name        varchar(60)  NOT NULL CONSTRAINT categories_name_check CHECK (btrim(name) <> ''),
  description varchar(250) NOT NULL DEFAULT '',
  status      varchar(10)  NOT NULL DEFAULT 'active'
              CONSTRAINT categories_status_check CHECK (status IN ('active', 'inactive')),
  created_at  timestamptz  NOT NULL DEFAULT now(),
  updated_at  timestamptz  NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX categories_name_key ON categories (lower(name));
CREATE TRIGGER categories_set_updated_at BEFORE UPDATE ON categories
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Brands
-- -----------------------------------------------------------------------------
CREATE TABLE brands (
  id          uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  name        varchar(60)  NOT NULL CONSTRAINT brands_name_check CHECK (btrim(name) <> ''),
  description varchar(250) NOT NULL DEFAULT '',
  status      varchar(10)  NOT NULL DEFAULT 'active'
              CONSTRAINT brands_status_check CHECK (status IN ('active', 'inactive')),
  created_at  timestamptz  NOT NULL DEFAULT now(),
  updated_at  timestamptz  NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX brands_name_key ON brands (lower(name));
CREATE TRIGGER brands_set_updated_at BEFORE UPDATE ON brands
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Sizes (S, M, L, 28, 30, Free Size, 2-3 Y …)
-- -----------------------------------------------------------------------------
CREATE TABLE sizes (
  id          uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  name        varchar(20)  NOT NULL CONSTRAINT sizes_name_check CHECK (btrim(name) <> ''),
  size_type   varchar(10)  NOT NULL DEFAULT 'clothing'
              CONSTRAINT sizes_size_type_check CHECK (size_type IN ('clothing', 'numeric', 'custom')),
  description varchar(250) NOT NULL DEFAULT '',
  status      varchar(10)  NOT NULL DEFAULT 'active'
              CONSTRAINT sizes_status_check CHECK (status IN ('active', 'inactive')),
  created_at  timestamptz  NOT NULL DEFAULT now(),
  updated_at  timestamptz  NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX sizes_name_key ON sizes (lower(name));
CREATE TRIGGER sizes_set_updated_at BEFORE UPDATE ON sizes
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Colors
-- -----------------------------------------------------------------------------
CREATE TABLE colors (
  id          uuid         PRIMARY KEY DEFAULT gen_random_uuid(),
  name        varchar(40)  NOT NULL CONSTRAINT colors_name_check CHECK (btrim(name) <> ''),
  hex_code    char(7)      NOT NULL CONSTRAINT colors_hex_code_check CHECK (hex_code ~ '^#[0-9A-F]{6}$'),
  description varchar(250) NOT NULL DEFAULT '',
  status      varchar(10)  NOT NULL DEFAULT 'active'
              CONSTRAINT colors_status_check CHECK (status IN ('active', 'inactive')),
  created_at  timestamptz  NOT NULL DEFAULT now(),
  updated_at  timestamptz  NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX colors_name_key ON colors (lower(name));
CREATE TRIGGER colors_set_updated_at BEFORE UPDATE ON colors
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Suppliers
-- -----------------------------------------------------------------------------
CREATE TABLE suppliers (
  id              uuid          PRIMARY KEY DEFAULT gen_random_uuid(),
  name            varchar(100)  NOT NULL CONSTRAINT suppliers_name_check CHECK (btrim(name) <> ''),
  contact_person  varchar(60)   NOT NULL DEFAULT '',
  mobile          varchar(10)   NOT NULL CONSTRAINT suppliers_mobile_check CHECK (mobile ~ '^[6-9][0-9]{9}$'),
  email           varchar(100)  NOT NULL DEFAULT '',
  address         varchar(250)  NOT NULL DEFAULT '',
  city            varchar(60)   NOT NULL DEFAULT '',
  state           varchar(60)   NOT NULL DEFAULT '',
  pincode         varchar(6)    NOT NULL DEFAULT ''
                  CONSTRAINT suppliers_pincode_check CHECK (pincode = '' OR pincode ~ '^[1-9][0-9]{5}$'),
  gst_number      varchar(15)   NOT NULL DEFAULT ''
                  CONSTRAINT suppliers_gst_number_check
                  CHECK (gst_number = '' OR gst_number ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$'),
  opening_balance numeric(12,2) NOT NULL DEFAULT 0
                  CONSTRAINT suppliers_opening_balance_check CHECK (opening_balance >= 0),
  status          varchar(10)   NOT NULL DEFAULT 'active'
                  CONSTRAINT suppliers_status_check CHECK (status IN ('active', 'inactive')),
  created_at      timestamptz   NOT NULL DEFAULT now(),
  updated_at      timestamptz   NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX suppliers_name_key ON suppliers (lower(name));
CREATE UNIQUE INDEX suppliers_gst_number_key ON suppliers (gst_number) WHERE gst_number <> '';
CREATE INDEX suppliers_mobile_idx ON suppliers (mobile);
CREATE TRIGGER suppliers_set_updated_at BEFORE UPDATE ON suppliers
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Customers (mobile number identifies a customer at the billing counter)
-- -----------------------------------------------------------------------------
CREATE TABLE customers (
  id              uuid          PRIMARY KEY DEFAULT gen_random_uuid(),
  name            varchar(100)  NOT NULL CONSTRAINT customers_name_check CHECK (btrim(name) <> ''),
  mobile          varchar(10)   NOT NULL CONSTRAINT customers_mobile_check CHECK (mobile ~ '^[6-9][0-9]{9}$'),
  email           varchar(100)  NOT NULL DEFAULT '',
  address         varchar(250)  NOT NULL DEFAULT '',
  city            varchar(60)   NOT NULL DEFAULT '',
  state           varchar(60)   NOT NULL DEFAULT '',
  pincode         varchar(6)    NOT NULL DEFAULT ''
                  CONSTRAINT customers_pincode_check CHECK (pincode = '' OR pincode ~ '^[1-9][0-9]{5}$'),
  gst_number      varchar(15)   NOT NULL DEFAULT ''
                  CONSTRAINT customers_gst_number_check
                  CHECK (gst_number = '' OR gst_number ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$'),
  opening_balance numeric(12,2) NOT NULL DEFAULT 0
                  CONSTRAINT customers_opening_balance_check CHECK (opening_balance >= 0),
  status          varchar(10)   NOT NULL DEFAULT 'active'
                  CONSTRAINT customers_status_check CHECK (status IN ('active', 'inactive')),
  created_at      timestamptz   NOT NULL DEFAULT now(),
  updated_at      timestamptz   NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX customers_mobile_key ON customers (mobile);
CREATE UNIQUE INDEX customers_gst_number_key ON customers (gst_number) WHERE gst_number <> '';
CREATE INDEX customers_name_idx ON customers (lower(name));
CREATE TRIGGER customers_set_updated_at BEFORE UPDATE ON customers
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Products
-- -----------------------------------------------------------------------------
CREATE TABLE products (
  id             uuid          PRIMARY KEY DEFAULT gen_random_uuid(),
  name           varchar(120)  NOT NULL CONSTRAINT products_name_check CHECK (btrim(name) <> ''),
  code           varchar(30)   NOT NULL CONSTRAINT products_code_check CHECK (code ~ '^[A-Z0-9][A-Z0-9_/-]*$'),
  category_id    uuid          NOT NULL
                 CONSTRAINT products_category_id_fkey REFERENCES categories (id) ON DELETE RESTRICT,
  brand_id       uuid
                 CONSTRAINT products_brand_id_fkey REFERENCES brands (id) ON DELETE RESTRICT,
  description    varchar(500)  NOT NULL DEFAULT '',
  product_type   varchar(20)   NOT NULL DEFAULT 'readymade'
                 CONSTRAINT products_product_type_check
                 CHECK (product_type IN ('readymade', 'fabric', 'accessory', 'footwear', 'other')),
  hsn_code       varchar(8)    NOT NULL DEFAULT ''
                 CONSTRAINT products_hsn_code_check CHECK (hsn_code = '' OR hsn_code ~ '^([0-9]{4}|[0-9]{6}|[0-9]{8})$'),
  gst_rate       numeric(5,2)  NOT NULL DEFAULT 5
                 CONSTRAINT products_gst_rate_check CHECK (gst_rate IN (0, 5, 12, 18, 28, 40)),
  mrp            numeric(12,2) NOT NULL CONSTRAINT products_mrp_check CHECK (mrp >= 0),
  purchase_price numeric(12,2) CONSTRAINT products_purchase_price_check CHECK (purchase_price >= 0),
  selling_price  numeric(12,2) NOT NULL
                 CONSTRAINT products_selling_price_check CHECK (selling_price >= 0 AND selling_price <= mrp),
  barcode        varchar(48)   NOT NULL DEFAULT '',
  status         varchar(10)   NOT NULL DEFAULT 'active'
                 CONSTRAINT products_status_check CHECK (status IN ('active', 'inactive')),
  created_at     timestamptz   NOT NULL DEFAULT now(),
  updated_at     timestamptz   NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX products_code_key ON products (lower(code));
CREATE UNIQUE INDEX products_barcode_key ON products (barcode) WHERE barcode <> '';
CREATE INDEX products_category_id_idx ON products (category_id);
CREATE INDEX products_brand_id_idx ON products (brand_id);
CREATE INDEX products_name_idx ON products (lower(name));
CREATE TRIGGER products_set_updated_at BEFORE UPDATE ON products
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- -----------------------------------------------------------------------------
-- Product variants (design / model number + size + colour)
-- Price columns are optional overrides; NULL means "use the product price".
-- -----------------------------------------------------------------------------
CREATE TABLE product_variants (
  id             uuid          PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id     uuid          NOT NULL
                 CONSTRAINT product_variants_product_id_fkey REFERENCES products (id) ON DELETE CASCADE,
  design_no      varchar(30)   NOT NULL DEFAULT '',
  size_id        uuid          NOT NULL
                 CONSTRAINT product_variants_size_id_fkey REFERENCES sizes (id) ON DELETE RESTRICT,
  color_id       uuid          NOT NULL
                 CONSTRAINT product_variants_color_id_fkey REFERENCES colors (id) ON DELETE RESTRICT,
  sku            varchar(60)   NOT NULL CONSTRAINT product_variants_sku_check CHECK (btrim(sku) <> ''),
  barcode        varchar(48)   NOT NULL DEFAULT '',
  purchase_price numeric(12,2) CONSTRAINT product_variants_purchase_price_check CHECK (purchase_price >= 0),
  selling_price  numeric(12,2) CONSTRAINT product_variants_selling_price_check CHECK (selling_price >= 0),
  mrp            numeric(12,2) CONSTRAINT product_variants_mrp_check CHECK (mrp >= 0),
  -- Display order within the product (as entered by staff).
  position       integer       NOT NULL DEFAULT 0,
  created_at     timestamptz   NOT NULL DEFAULT now(),
  updated_at     timestamptz   NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX product_variants_sku_key ON product_variants (lower(sku));
CREATE UNIQUE INDEX product_variants_barcode_key ON product_variants (barcode) WHERE barcode <> '';
CREATE UNIQUE INDEX product_variants_combo_key
  ON product_variants (product_id, lower(design_no), size_id, color_id);
CREATE INDEX product_variants_product_id_idx ON product_variants (product_id, position);
CREATE INDEX product_variants_size_id_idx ON product_variants (size_id);
CREATE INDEX product_variants_color_id_idx ON product_variants (color_id);
CREATE TRIGGER product_variants_set_updated_at BEFORE UPDATE ON product_variants
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();
